package com.rikkeibank.account.service;import com.rikkeibank.account.domain.*;import com.rikkeibank.account.repo.*;import com.rikkeibank.common.api.BusinessException;import org.springframework.data.domain.*;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import java.math.*;import java.security.SecureRandom;import java.util.*;
@Service public class AccountService{private final AccountRepository accounts;private final AccountTypeRepository types;private final LedgerOperationRepository operations;private final SecureRandom random=new SecureRandom();public AccountService(AccountRepository a,AccountTypeRepository t,LedgerOperationRepository o){accounts=a;types=t;operations=o;}@Transactional public Account create(UUID customerId,UUID typeId,BigDecimal initial){AccountType t=types.findById(typeId).filter(AccountType::isActive).orElseThrow(()->BusinessException.badRequest("INVALID_ACCOUNT_TYPE","Account type is invalid"));BigDecimal b=money(initial);if(b.compareTo(t.getMinimumBalance())<0)throw BusinessException.badRequest("MINIMUM_BALANCE","Initial balance is below minimum");String number;do{number="1001"+(100000000000L+Math.abs(random.nextLong()%899999999999L));}while(accounts.existsByAccountNumber(number));return accounts.save(new Account(number,customerId,typeId,b));}public Account get(UUID id){return accounts.findById(id).orElseThrow(()->BusinessException.notFound("Account not found"));}public Page<Account> list(Pageable p){return accounts.findAll(p);}public List<Account> byCustomer(UUID id){return accounts.findByCustomerId(id);}@Transactional public Account update(UUID id,UUID typeId,Account.Status status){if(!types.existsById(typeId))throw BusinessException.badRequest("INVALID_ACCOUNT_TYPE","Account type is invalid");Account a=get(id);a.update(typeId,status);return a;}@Transactional public void delete(UUID id){Account a=get(id);if(a.getBalance().signum()!=0)throw BusinessException.conflict("NON_ZERO_BALANCE","Cannot delete an account with a balance");accounts.delete(a);}
 @Transactional public Account debit(UUID operationId,UUID accountId,UUID customerId,BigDecimal value){if(operations.existsByOperationIdAndKind(operationId,"DEBIT"))return get(accountId);Account a=locked(accountId);if(!a.getCustomerId().equals(customerId))throw new BusinessException(org.springframework.http.HttpStatus.FORBIDDEN,"ACCOUNT_OWNERSHIP","Source account does not belong to customer");BigDecimal amount=positive(value);if(a.getBalance().compareTo(amount)<0)throw BusinessException.badRequest("INSUFFICIENT_FUNDS","Insufficient balance");a.debit(amount);operations.save(new LedgerOperation(operationId,accountId,"DEBIT",amount));return a;}
 @Transactional public Account credit(UUID operationId,UUID accountId,BigDecimal value){if(operations.existsByOperationIdAndKind(operationId,"CREDIT"))return get(accountId);Account a=locked(accountId);BigDecimal amount=positive(value);a.credit(amount);operations.save(new LedgerOperation(operationId,accountId,"CREDIT",amount));return a;}
 @Transactional public Account refund(UUID operationId,UUID accountId,BigDecimal value){if(operations.existsByOperationIdAndKind(operationId,"REFUND"))return get(accountId);Account a=locked(accountId);BigDecimal amount=positive(value);a.credit(amount);operations.save(new LedgerOperation(operationId,accountId,"REFUND",amount));return a;}
 private Account locked(UUID id){Account a=accounts.lock(id).orElseThrow(()->BusinessException.notFound("Account not found"));if(a.getStatus()!=Account.Status.ACTIVE)throw BusinessException.conflict("ACCOUNT_INACTIVE","Account is not active");return a;}private BigDecimal positive(BigDecimal v){BigDecimal a=money(v);if(a.signum()<=0)throw BusinessException.badRequest("INVALID_AMOUNT","Amount must be positive");return a;}private BigDecimal money(BigDecimal v){return (v==null?BigDecimal.ZERO:v).setScale(2,RoundingMode.HALF_EVEN);}}
